const input = $input.first().json;
const company = String(input.company || input['Company'] || '').trim().replace(/\s+/g, ' ');
const objective = String(input.objective || input['Research objective'] || '').trim().replace(/\s+/g, ' ');
if (company.length < 2 || company.length > 200) throw new Error('Company must be 2-200 characters.');
if (objective.length < 20 || objective.length > 2000) throw new Error('Objective must be 20-2000 characters.');
const crypto = require('crypto');
const dedupe_key = crypto.createHash('sha256').update(company.toLowerCase() + '|' + objective.toLowerCase() + '|v1').digest('hex').slice(0, 32);
return [{ json: { company, objective, dedupe_key, report_version: 'v1', status: 'processing', started_at: new Date().toISOString() } }];

const row = $input.first().json;
const report = typeof row.report_json === 'string' ? JSON.parse(row.report_json) : row.report_json;
return [{ json: { ...report, cache_hit: true, message: 'Existing assessment reused — zero API calls made.' } }];

const raw = $input.first().json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Planner returned empty content.');
let plan; try { plan = JSON.parse(raw); } catch { throw new Error('Planner output is not valid JSON.'); }
if (!Array.isArray(plan.queries) || !plan.queries.length) throw new Error('Plan has no queries.');
return plan.queries.slice(0, 4).map((q, i) => {
  if (!q.query || !q.topic || !q.reason) throw new Error('Invalid query at ' + i);
  return { json: { query: q.query.slice(0, 400), topic: q.topic, reason: q.reason, round: 0 } };
});

const items = $input.all();
const seen = new Set(); const urls = []; const trace = [];
const isHttp = u => /^https?:\/\//i.test(u);
for (const item of items) {
  const r = item.json;
  trace.push({ round: 0, action: 'search', query: r.query, result_count: (r.results || []).length });
  for (const res of r.results || []) {
    const u = String(res.url || '').trim();
    if (isHttp(u) && !seen.has(u)) { seen.add(u); urls.push({ url: u, title: res.title || '' }); }
  }
}
if (!urls.length) throw new Error('Tavily Search returned no valid URLs.');
return [{ json: { urls: urls.slice(0, 10), trace, searches: items.length } }];

const r = $input.first().json;
const titles = new Map($('Collect URLs R1').first().json.urls.map(u => [u.url, u.title]));
const ok = (r.results || []).filter(x => x.url && x.raw_content).map(x => ({ url: x.url, title: titles.get(x.url) || '', content: String(x.raw_content).slice(0, 8000), status: 'ok' }));
const failed = (r.failed_results || []).map(f => ({ url: f.url, error: String(f.error || 'extract failed').slice(0, 300) }));
if (!ok.length) throw new Error('Tavily Extract produced zero usable sources.');
return [{ json: { sources: ok, failed_results: failed, round: 0 } }];

const raw = $input.first().json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Verifier returned empty content.');
let rep; try { rep = JSON.parse(raw); } catch { throw new Error('Verifier output is not valid JSON.'); }
if (!Array.isArray(rep.findings) || typeof rep.assessment !== 'string') throw new Error('invalid_schema');
const srcs = $('Build Evidence R1').first().json.sources;
const norm = u => { try { const x = new URL(u); x.hash=''; ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid','ref','source'].forEach(p=>x.searchParams.delete(p)); return x.href.replace(/\/$/, '').toLowerCase(); } catch { return String(u||'').toLowerCase(); } };
const map = new Map(srcs.map(s => [norm(s.url), s]));
const canon = t => String(t||'').normalize('NFC').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[\u2013\u2014\u2010\u2011\u2012]/g,'-').replace(/\u00A0/g,' ').replace(/\s+/g,' ');
const V = new Set(['supported','contradicted','insufficient_evidence']);
const S = new Set(['info','low','medium','high','critical']);
const MATERIAL = new Set(['breach','litigation','sanctions','fraud','security','reliability','compliance']);
let downgraded = 0, normalizedOnly = 0, retrievable = [];
const findings = rep.findings.map(f => {
  const v = { original_state: f.verification, final_state: f.verification, url_match: false, evidence_match: 'none', downgrade_reason: 'none', severity_adjusted: false };
  if (!f.claim || !f.topic || !V.has(f.verification) || !S.has(f.severity)) { v.final_state='insufficient_evidence'; v.downgrade_reason='invalid_finding'; }
  const src = map.get(norm(f.source_url));
  const ev = String(f.evidence||'').trim();
  const badFormat = ev.length<20 || ev.length>2000 || /(\u2026|\.\.\.|\[\.\.\.\])/.test(ev);
  if (f.verification !== 'insufficient_evidence') {
    if (!src) { v.final_state='insufficient_evidence'; v.downgrade_reason='url_not_in_extraction_set'; if (f.source_url) retrievable.push(f.topic); }
    else { v.url_match = true;
      if (badFormat) { v.final_state='insufficient_evidence'; v.downgrade_reason='evidence_format_invalid'; }
      else { const exact = src.content.normalize('NFC').replace(/\s+/g,' ').includes(ev.normalize('NFC').replace(/\s+/g,' '));
        const normMatch = !exact && canon(src.content).includes(canon(ev));
        if (exact) v.evidence_match='exact'; else if (normMatch) v.evidence_match='normalized';
        else { v.final_state='insufficient_evidence'; v.downgrade_reason='evidence_not_found_in_source'; }
      }
    }
  }
  if (v.final_state !== f.verification) downgraded++;
  if (v.evidence_match === 'normalized') normalizedOnly++;
  if (v.final_state === 'contradicted' && ['info','low'].includes(f.severity)) { f.severity='medium'; v.severity_adjusted=true; }
  if (v.final_state === 'insufficient_evidence' && ['high','critical'].includes(f.severity) && !MATERIAL.has(f.topic)) { f.severity='medium'; v.severity_adjusted=true; }
  return { ...f, verification: v.final_state, source_url: src ? f.source_url : '', source_title: src ? (f.source_title || src.title) : '', evidence: v.evidence_match==='none'&&v.final_state!=='insufficient_evidence' ? ev : (v.final_state==='insufficient_evidence'?'':ev), validation: v, compound: String(f.claim).length>300 };
});
const materialInsuff = findings.filter(f => MATERIAL.has(f.topic) && f.verification==='insufficient_evidence').length;
const reasons = [];
if (findings.some(f=>f.verification==='contradicted')) reasons.push('contradicted_finding');
if (normalizedOnly) reasons.push('normalized_match_audit');
if (downgraded>=2) reasons.push('downgrade_threshold');
if (materialInsuff >= Math.ceil(findings.filter(f=>MATERIAL.has(f.topic)).length/2) && findings.some(f=>MATERIAL.has(f.topic))) reasons.push('material_insufficiency');
if (findings.some(f=>f.compound)) reasons.push('compound_claim_suspected');
const needsFollowUp = Boolean(rep.needs_more_research && retrievable.length && rep.follow_up_queries?.length);
return [{ json: { findings, assessment: rep.assessment, needs_follow_up: needsFollowUp, follow_up_queries: needsFollowUp ? rep.follow_up_queries.slice(0,3) : [], review_reasons: reasons, downgraded, round: 0 } }];

const items = $input.all();
const seen0 = new Set($('Build Evidence R1').first().json.sources.map(s => s.url));
const seen = new Set(); const urls = []; const trace = [];
const isHttp = u => /^https?:\/\//i.test(u);
for (const item of items) {
  const r = item.json;
  trace.push({ round: 1, action: 'search', query: r.query, result_count: (r.results || []).length, follow_up_reason: r.reason || 'gap' });
  for (const res of r.results || []) {
    const u = String(res.url || '').trim();
    if (isHttp(u) && !seen.has(u) && !seen0.has(u)) { seen.add(u); urls.push({ url: u, title: res.title || '' }); }
  }
}
if (!urls.length) throw new Error('Tavily Search returned no valid URLs.');
return [{ json: { urls: urls.slice(0, 10), trace, searches: items.length, new_count: urls.length } }];

const r = $input.first().json;
const first = $('Build Evidence R1').first().json;
const titles = new Map($('Collect URLs R2').first().json.urls.map(u => [u.url, u.title]));
const ok2 = (r.results || []).filter(x => x.url && x.raw_content).map(x => ({ url: x.url, title: titles.get(x.url) || '', content: String(x.raw_content).slice(0, 8000), status: 'ok' }));
return [{ json: { sources: [...first.sources, ...ok2], failed_results: [...first.failed_results, ...(r.failed_results || [])], round: 1 } }];

const raw = $input.first().json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Final verifier returned empty content.');
let rep; try { rep = JSON.parse(raw); } catch { throw new Error('Final verifier output is not valid JSON.'); }
const srcs = $('Merge Evidence').first().json.sources;
const norm = u => { try { const x = new URL(u); x.hash=''; ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid','ref','source'].forEach(p=>x.searchParams.delete(p)); return x.href.replace(/\/$/, '').toLowerCase(); } catch { return String(u||'').toLowerCase(); } };
const map = new Map(srcs.map(s => [norm(s.url), s]));
const canon = t => String(t||'').normalize('NFC').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[\u2013\u2014\u2010\u2011\u2012]/g,'-').replace(/\u00A0/g,' ').replace(/\s+/g,' ');
const MATERIAL = new Set(['breach','litigation','sanctions','fraud','security','reliability','compliance']);
let downgraded=0, normalizedOnly=0;
const findings = rep.findings.map(f => {
  const v = { original_state: f.verification, final_state: f.verification, url_match: false, evidence_match: 'none', downgrade_reason: 'none', severity_adjusted: false };
  const src = map.get(norm(f.source_url)); const ev = String(f.evidence||'').trim();
  const badFormat = ev.length<20 || ev.length>2000 || /(\u2026|\.\.\.|\[\.\.\.\])/.test(ev);
  if (f.verification !== 'insufficient_evidence') {
    if (!src) { v.final_state='insufficient_evidence'; v.downgrade_reason='url_not_in_extraction_set'; }
    else { v.url_match=true;
      if (badFormat) { v.final_state='insufficient_evidence'; v.downgrade_reason='evidence_format_invalid'; }
      else { const exact = src.content.normalize('NFC').replace(/\s+/g,' ').includes(ev.normalize('NFC').replace(/\s+/g,' '));
        const nm = !exact && canon(src.content).includes(canon(ev));
        if (exact) v.evidence_match='exact'; else if (nm) v.evidence_match='normalized';
        else { v.final_state='insufficient_evidence'; v.downgrade_reason='evidence_not_found_in_source'; } }
    }
  }
  if (v.final_state !== f.verification) downgraded++;
  if (v.evidence_match==='normalized') normalizedOnly++;
  if (v.final_state==='contradicted' && ['info','low'].includes(f.severity)) { f.severity='medium'; v.severity_adjusted=true; }
  return { ...f, verification: v.final_state, source_url: src ? f.source_url : '', evidence: v.final_state==='insufficient_evidence'?'':ev, validation: v, compound: String(f.claim).length>300 };
});
const reasons = [];
if (findings.some(f=>f.verification==='contradicted')) reasons.push('contradicted_finding');
if (normalizedOnly) reasons.push('normalized_match_audit');
if (downgraded>=2) reasons.push('downgrade_threshold');
if (findings.some(f=>f.compound)) reasons.push('compound_claim_suspected');
return [{ json: { findings, assessment: rep.assessment, review_reasons: reasons, downgraded, round: 1 } }];

const rep = $input.first().json;
const norm = $('Normalize + Fingerprint').first().json;
const trace = [...$('Collect URLs R1').first().json.trace];
const searches = $('Collect URLs R1').first().json.searches;
let extracts = 1, r2 = 0;
try { const c2 = $('Collect URLs R2').first().json; trace.push(...c2.trace); extracts = c2.new_count>0?2:1; r2 = c2.searches||0; } catch {}
const requires_review = rep.review_reasons.length>0 || rep.findings.some(f=>['high','critical'].includes(f.severity));
return [{ json: { vendor: norm.company, objective: norm.objective, generated_at: new Date().toISOString(), status: rep.downgraded>0?'degraded':'complete', requires_review, review_reasons: rep.review_reasons, findings: rep.findings, assessment: rep.assessment, trace, usage: { model_calls: rep.round>0?3:2, search_calls: searches+r2, extract_calls: extracts, research_rounds: rep.round+1 }, validator_version: '1.0.0', model: 'MiniMaxAI/MiniMax-M3', dedupe_key: norm.dedupe_key, report_version: 'v1', cache_hit: false } }];
